namespace Atm;

public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
{
    private const int DailyLimit = 200;
    private const int FeeThreshold = 100;
    private const int WithdrawalFee = 5;
    private const int CassetteCapacity = 5;
    private const int MaxNotesPerPass = 4;

    private static readonly Denomination[] Denominations = [Denomination.Fifty, Denomination.Twenty, Denomination.Ten];

    public AtmResult Execute(AccountState account, Operation operation)
    {
        ArgumentNullException.ThrowIfNull(operation);

        return operation switch
        {
            Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
            Operation.Deposit deposit => Deposit(account, deposit.Notes),
            _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}.", nameof(operation)),
        };
    }

    private AtmResult Withdraw(AccountState account, int amount)
    {
        if (amount <= 0 || amount % 10 != 0)
        {
            return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (account.WithdrawnToday + amount > DailyLimit)
        {
            return Refuse(AtmStatus.DailyLimitExceeded, account);
        }

        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
        if (amount + fee > account.Balance)
        {
            return Refuse(AtmStatus.InsufficientFunds, account);
        }

        if (FewestNotes(amount, Available()) is not { } combination)
        {
            return Refuse(AtmStatus.CannotDispense, account);
        }

        var dispensed = NoteCounts.None;
        foreach (var pass in Passes(combination))
        {
            if (!dispenser.Dispense(pass))
            {
                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
            }

            dispensed += pass;
        }

        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);

        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    }

    private AtmResult Deposit(AccountState account, NoteCounts notes)
    {
        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total == 0)
        {
            return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
        {
            return Refuse(AtmStatus.CassetteJammed, account);
        }

        var after = dispenser.Stock + notes;
        if (Denominations.Any(denomination => after.Of(denomination) > CassetteCapacity))
        {
            return Refuse(AtmStatus.CassetteFull, account);
        }

        if (!dispenser.Load(notes))
        {
            return Refuse(AtmStatus.DispenserFault, account);
        }

        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    }

    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
        new(status, NoteCounts.None, 0, account);

    /// <summary>Les billets disponibles : le stock, sans la cassette bloquée.</summary>
    private NoteCounts Available()
    {
        var stock = dispenser.Stock;
        var jammed = dispenser.Jammed;

        int Count(Denomination denomination) =>
            denomination == jammed ? 0 : Math.Max(0, stock.Of(denomination));

        return new NoteCounts(Count(Denomination.Fifty), Count(Denomination.Twenty), Count(Denomination.Ten));
    }

    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
    {
        NoteCounts? best = null;
        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
        {
            var afterFifties = amount - fifties * 50;
            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
            {
                var rest = afterFifties - twenties * 20;
                var tens = rest / 10;
                if (rest % 10 != 0 || tens > available.Tens)
                {
                    continue;
                }

                var candidate = new NoteCounts(fifties, twenties, tens);
                if (best is not { } current || candidate.Total < current.Total)
                {
                    best = candidate;
                }
            }
        }

        return best;
    }

    /// <summary>Découpe la combinaison en passages d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
    {
        var remaining = notes;
        while (remaining.Total > 0)
        {
            var room = MaxNotesPerPass;
            var fifties = Math.Min(room, remaining.Fifties);
            room -= fifties;
            var twenties = Math.Min(room, remaining.Twenties);
            room -= twenties;
            var tens = Math.Min(room, remaining.Tens);

            var pass = new NoteCounts(fifties, twenties, tens);
            remaining -= pass;

            yield return pass;
        }
    }
}
namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}
namespace Atm.Tests;

public class DepositTests
{
    private static (AtmResult Result, RecordingDispenser Dispenser) Run(
        int balance, int withdrawnToday, NoteCounts stock, Denomination? jammed, NoteCounts notes, bool failLoad = false)
    {
        var dispenser = new RecordingDispenser(new MoneyDispenser(stock, jammed), failLoad: failLoad);
        var result = new CashMachine(dispenser).Execute(new AccountState(balance, withdrawnToday), new Operation.Deposit(notes));

        return (result, dispenser);
    }

    private static void AssertRefused(AtmStatus expected, AtmResult result, RecordingDispenser dispenser, AccountState account, NoteCounts stock)
    {
        Assert.Equal(new AtmResult(expected, NoteCounts.None, 0, account), result);
        Assert.Equal(stock, dispenser.Stock);
        Assert.Empty(dispenser.LoadCalls);
        Assert.Empty(dispenser.DispenseCalls);
    }

    [Fact]
    public void Deposit_IntoFullCassette_IsRefused()
    {
        var (result, dispenser) = Run(10, 0, new(0, 5, 0), null, new(0, 1, 0));

        AssertRefused(AtmStatus.CassetteFull, result, dispenser, new(10, 0), new(0, 5, 0));
    }

    [Fact]
    public void Deposit_IntoJammedCassette_IsRefused()
    {
        var (result, dispenser) = Run(10, 30, new(0, 1, 0), Denomination.Twenty, new(0, 1, 0));

        AssertRefused(AtmStatus.CassetteJammed, result, dispenser, new(10, 30), new(0, 1, 0));
    }

    [Fact]
    public void Deposit_Succeeds()
    {
        var (result, dispenser) = Run(10, 30, new(1, 1, 0), null, new(1, 0, 1));

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new(70, 30)), result);
        Assert.Equal(new NoteCounts(2, 1, 1), dispenser.Stock);
    }

    [Fact]
    public void Deposit_WithJammedCassetteNotTouched_Succeeds()
    {
        var (result, dispenser) = Run(0, 0, new(5, 0, 0), Denomination.Fifty, new(0, 1, 1));

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new(30, 0)), result);
        Assert.Equal(new NoteCounts(5, 1, 1), dispenser.Stock);
    }

    [Fact]
    public void EmptyDeposit_IsInvalidAmount_BeforeOtherChecks()
    {
        var (result, dispenser) = Run(10, 0, new(5, 5, 5), Denomination.Ten, NoteCounts.None);

        AssertRefused(AtmStatus.InvalidAmount, result, dispenser, new(10, 0), new(5, 5, 5));
    }

    [Fact]
    public void NegativeDeposit_IsInvalidAmount()
    {
        var (result, dispenser) = Run(10, 0, new(1, 1, 1), null, new(1, -1, 0));

        AssertRefused(AtmStatus.InvalidAmount, result, dispenser, new(10, 0), new(1, 1, 1));
    }

    [Fact]
    public void Jammed_IsCheckedBeforeFull()
    {
        var (result, _) = Run(10, 0, new(0, 0, 5), Denomination.Fifty, new(1, 0, 1));

        Assert.Equal(AtmStatus.CassetteJammed, result.Status);
    }

    [Fact]
    public void Deposit_FillingCassetteExactly_Succeeds()
    {
        var (result, dispenser) = Run(0, 0, new(4, 4, 4), null, new(1, 1, 1));

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(new AccountState(80, 0), result.Account);
        Assert.Equal(new NoteCounts(5, 5, 5), dispenser.Stock);
    }

    [Fact]
    public void LoadFailure_IsDispenserFault()
    {
        var (result, dispenser) = Run(10, 20, new(1, 1, 1), null, new(1, 0, 0), failLoad: true);

        Assert.Equal(new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, new(10, 20)), result);
        Assert.Single(dispenser.LoadCalls);
        Assert.Equal(new NoteCounts(1, 1, 1), dispenser.Stock);
    }
}
namespace Atm.Tests;

public class MachineTests
{
    private static readonly Denomination?[] JamOptions = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];

    private static IEnumerable<NoteCounts> AllStocks() =>
        from f in Enumerable.Range(0, 6)
        from t in Enumerable.Range(0, 6)
        from n in Enumerable.Range(0, 6)
        select new NoteCounts(f, t, n);

    [Fact]
    public void NullOperation_Throws()
    {
        var machine = new CashMachine(new MoneyDispenser(NoteCounts.None));

        Assert.Throws<ArgumentNullException>(() => machine.Execute(new(0, 0), null!));
    }

    [Fact]
    public void UnknownOperation_Throws()
    {
        var machine = new CashMachine(new MoneyDispenser(NoteCounts.None));

        Assert.Throws<ArgumentException>(() => machine.Execute(new(0, 0), new UnknownOperation()));
    }

    [Fact]
    public void Machine_IsStatelessBetweenCalls()
    {
        var dispenser = new MoneyDispenser(new(5, 5, 5));
        var machine = new CashMachine(dispenser);

        var first = machine.Execute(new(250, 0), new Operation.Withdraw(100));
        var second = machine.Execute(new(250, 0), new Operation.Withdraw(100));

        Assert.Equal(first, second);
        Assert.Equal(new NoteCounts(1, 5, 5), dispenser.Stock);
    }

    /// <summary>
    /// Parcourt tous les stocks, cassettes bloquées et montants du domaine, et compare le retrait à un oracle
    /// qui énumère toutes les combinaisons.
    /// </summary>
    [Fact]
    public void Withdraw_MatchesOracle_OverWholeStockDomain()
    {
        int[] amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];

        foreach (var stock in AllStocks())
        foreach (var jammed in JamOptions)
        foreach (var amount in amounts)
        {
            var account = new AccountState(250, 0);
            var dispenser = new RecordingDispenser(new MoneyDispenser(stock, jammed));
            var result = new CashMachine(dispenser).Execute(account, new Operation.Withdraw(amount));

            var expected = Oracle(account, stock, jammed, amount);
            Assert.Equal(expected, result);
            Assert.Equal(stock - result.Notes, dispenser.Stock);
            Assert.All(dispenser.DispenseCalls, pass => Assert.InRange(pass.Total, 1, MoneyDispenser.MaxNotesPerPass));
        }
    }

    [Fact]
    public void Withdraw_RespectsAccountChecks_OverAccountDomain()
    {
        var stock = new NoteCounts(5, 5, 5);
        for (var balance = 0; balance <= 250; balance += 5)
        for (var withdrawn = 0; withdrawn <= 200; withdrawn += 10)
        for (var amount = 10; amount <= 220; amount += 10)
        {
            var account = new AccountState(balance, withdrawn);
            var result = new CashMachine(new MoneyDispenser(stock)).Execute(account, new Operation.Withdraw(amount));

            Assert.Equal(Oracle(account, stock, null, amount), result);
        }
    }

    [Fact]
    public void Deposit_MatchesOracle_OverWholeDomain()
    {
        var deposits =
            from f in Enumerable.Range(0, 2)
            from t in Enumerable.Range(0, 2)
            from n in Enumerable.Range(0, 2)
            select new NoteCounts(f, t, n);

        foreach (var stock in AllStocks())
        foreach (var jammed in JamOptions)
        foreach (var notes in deposits)
        {
            var account = new AccountState(100, 50);
            var dispenser = new MoneyDispenser(stock, jammed);
            var result = new CashMachine(dispenser).Execute(account, new Operation.Deposit(notes));

            AtmStatus status;
            if (notes.Total == 0) status = AtmStatus.InvalidAmount;
            else if (jammed is { } j && notes.Of(j) > 0) status = AtmStatus.CassetteJammed;
            else if ((stock + notes) is var after && (after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5)) status = AtmStatus.CassetteFull;
            else status = AtmStatus.Ok;

            var ok = status == AtmStatus.Ok;
            Assert.Equal(new AtmResult(status, NoteCounts.None, 0, ok ? new(100 + notes.Value, 50) : account), result);
            Assert.Equal(ok ? stock + notes : stock, dispenser.Stock);
        }
    }

    private static AtmResult Oracle(AccountState account, NoteCounts stock, Denomination? jammed, int amount)
    {
        AtmResult Refused(AtmStatus status) => new(status, NoteCounts.None, 0, account);

        if (amount <= 0 || amount % 10 != 0) return Refused(AtmStatus.InvalidAmount);
        if (account.WithdrawnToday + amount > 200) return Refused(AtmStatus.DailyLimitExceeded);
        var fee = amount > 100 ? 5 : 0;
        if (amount + fee > account.Balance) return Refused(AtmStatus.InsufficientFunds);

        var f = jammed == Denomination.Fifty ? 0 : stock.Fifties;
        var t = jammed == Denomination.Twenty ? 0 : stock.Twenties;
        var n = jammed == Denomination.Ten ? 0 : stock.Tens;
        var candidates = (
            from a in Enumerable.Range(0, f + 1)
            from b in Enumerable.Range(0, t + 1)
            from c in Enumerable.Range(0, n + 1)
            let notes = new NoteCounts(a, b, c)
            where notes.Value == amount
            select notes).ToList();

        if (candidates.Count == 0) return Refused(AtmStatus.CannotDispense);

        var fewest = candidates.Min(x => x.Total);
        var best = Assert.Single(candidates, x => x.Total == fewest);

        return new AtmResult(AtmStatus.Ok, best, fee, new(account.Balance - amount - fee, account.WithdrawnToday + amount));
    }
}
namespace Atm.Tests;

/// <summary>Enveloppe le vrai module, enregistre les appels et peut tomber en panne au n-ième appel.</summary>
internal sealed class RecordingDispenser(IMoneyDispenser inner, int? failOnDispenseCall = null, bool failLoad = false)
    : IMoneyDispenser
{
    public List<NoteCounts> DispenseCalls { get; } = [];

    public List<NoteCounts> LoadCalls { get; } = [];

    public NoteCounts Stock => inner.Stock;

    public Denomination? Jammed => inner.Jammed;

    public bool Dispense(NoteCounts notes)
    {
        DispenseCalls.Add(notes);

        return DispenseCalls.Count != failOnDispenseCall && inner.Dispense(notes);
    }

    public bool Load(NoteCounts notes)
    {
        LoadCalls.Add(notes);

        return !failLoad && inner.Load(notes);
    }
}

internal sealed record UnknownOperation : Operation;
namespace Atm.Tests;

public class WithdrawTests
{
    private static NoteCounts Full => new(5, 5, 5);

    private static (AtmResult Result, RecordingDispenser Dispenser) Run(
        int balance, int withdrawnToday, NoteCounts stock, Denomination? jammed, int amount)
    {
        var dispenser = new RecordingDispenser(new MoneyDispenser(stock, jammed));
        var result = new CashMachine(dispenser).Execute(new AccountState(balance, withdrawnToday), new Operation.Withdraw(amount));

        return (result, dispenser);
    }

    private static void AssertRefused(AtmStatus expected, AtmResult result, RecordingDispenser dispenser, AccountState account, NoteCounts stock)
    {
        Assert.Equal(new AtmResult(expected, NoteCounts.None, 0, account), result);
        Assert.Equal(stock, dispenser.Stock);
        Assert.Empty(dispenser.DispenseCalls);
        Assert.Empty(dispenser.LoadCalls);
    }

    // Exemples de la spécification.

    [Fact]
    public void Withdraw60_WithOnlyTwenties_GivesThreeTwenties()
    {
        var (result, dispenser) = Run(100, 0, new(1, 3, 0), null, 60);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(0, 3, 0), 0, new(40, 60)), result);
        Assert.Equal(new NoteCounts(1, 0, 0), dispenser.Stock);
    }

    [Fact]
    public void Withdraw80_UsesOneOfEach()
    {
        var (result, dispenser) = Run(100, 0, new(1, 1, 1), null, 80);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(1, 1, 1), 0, new(20, 80)), result);
        Assert.Equal(NoteCounts.None, dispenser.Stock);
    }

    [Fact]
    public void Withdraw100_HasNoFee()
    {
        var (result, _) = Run(105, 0, Full, null, 100);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(2, 0, 0), 0, new(5, 100)), result);
    }

    [Fact]
    public void Withdraw110_HasFiveEuroFee()
    {
        var (result, dispenser) = Run(115, 0, Full, null, 110);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(2, 0, 1), 5, new(0, 110)), result);
        Assert.Equal(new NoteCounts(3, 5, 4), dispenser.Stock);
    }

    [Fact]
    public void Withdraw110_WithoutRoomForFee_IsInsufficientFunds()
    {
        var (result, dispenser) = Run(110, 0, Full, null, 110);

        AssertRefused(AtmStatus.InsufficientFunds, result, dispenser, new(110, 0), Full);
    }

    [Fact]
    public void Withdraw_OverDailyLimit_IsRefused()
    {
        var (result, dispenser) = Run(250, 150, Full, null, 60);

        AssertRefused(AtmStatus.DailyLimitExceeded, result, dispenser, new(250, 150), Full);
    }

    [Fact]
    public void Withdraw_FromJammedCassetteOnly_CannotDispense()
    {
        var (result, dispenser) = Run(250, 0, new(1, 0, 0), Denomination.Fifty, 50);

        AssertRefused(AtmStatus.CannotDispense, result, dispenser, new(250, 0), new(1, 0, 0));
    }

    [Fact]
    public void Withdraw_AvoidsJammedCassette()
    {
        var (result, dispenser) = Run(250, 0, new(2, 2, 0), Denomination.Fifty, 40);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(0, 2, 0), 0, new(210, 40)), result);
        Assert.Equal(new NoteCounts(2, 0, 0), dispenser.Stock);
    }

    [Fact]
    public void Withdraw5_IsInvalidAmount()
    {
        var (result, dispenser) = Run(0, 200, NoteCounts.None, null, 5);

        AssertRefused(AtmStatus.InvalidAmount, result, dispenser, new(0, 200), NoteCounts.None);
    }

    // Contrôles et leur ordre.

    [Theory]
    [InlineData(-10)]
    [InlineData(0)]
    [InlineData(5)]
    [InlineData(15)]
    public void InvalidAmount_IsCheckedFirst(int amount)
    {
        // Le compte dépasse aussi le plafond et n'a pas de fonds : le montant est contrôlé avant.
        var (result, dispenser) = Run(0, 200, NoteCounts.None, null, amount);

        AssertRefused(AtmStatus.InvalidAmount, result, dispenser, new(0, 200), NoteCounts.None);
    }

    [Fact]
    public void DailyLimit_IsCheckedBeforeFunds()
    {
        var (result, _) = Run(0, 200, NoteCounts.None, null, 10);

        Assert.Equal(AtmStatus.DailyLimitExceeded, result.Status);
    }

    [Fact]
    public void DailyLimit_ReachedExactly_IsAllowed()
    {
        var (result, _) = Run(250, 150, Full, null, 50);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(1, 0, 0), 0, new(200, 200)), result);
    }

    [Fact]
    public void Withdraw220_ExceedsDailyLimit()
    {
        var (result, _) = Run(250, 0, Full, null, 220);

        Assert.Equal(AtmStatus.DailyLimitExceeded, result.Status);
    }

    [Fact]
    public void Funds_AreCheckedBeforeDispensability()
    {
        var (result, _) = Run(20, 0, NoteCounts.None, null, 30);

        Assert.Equal(AtmStatus.InsufficientFunds, result.Status);
    }

    [Fact]
    public void Funds_ExactBalanceWithoutFee_IsAllowed()
    {
        var (result, _) = Run(100, 0, Full, null, 100);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(2, 0, 0), 0, new(0, 100)), result);
    }

    [Fact]
    public void Fee_DoesNotCountTowardDailyLimit()
    {
        var (result, _) = Run(250, 0, Full, null, 200);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(4, 0, 0), 5, new(45, 200)), result);
    }

    [Fact]
    public void CannotDispense_WhenNoExactCombination()
    {
        var (result, dispenser) = Run(250, 0, new(1, 0, 0), null, 30);

        AssertRefused(AtmStatus.CannotDispense, result, dispenser, new(250, 0), new(1, 0, 0));
    }

    [Fact]
    public void FewestNotes_PrefersFiftyAndTenOverThreeTwenties()
    {
        var (result, _) = Run(250, 0, Full, null, 60);

        Assert.Equal(new NoteCounts(1, 0, 1), result.Notes);
    }

    [Fact]
    public void FewestNotes_UsesTwentiesWhenFiftyWouldStrandAnOddRemainder()
    {
        // 80 = 50 + 20 + 10 (3 billets) ou 20×4 (4 billets) ; sans billet de 10, seule 20×4 convient.
        var (result, _) = Run(250, 0, new(5, 5, 0), null, 80);

        Assert.Equal(new NoteCounts(0, 4, 0), result.Notes);
    }

    [Fact]
    public void FewestNotes_WithJammedTwenties_FallsBackOnTens()
    {
        var (result, _) = Run(250, 0, Full, Denomination.Twenty, 90);

        Assert.Equal(new NoteCounts(1, 0, 4), result.Notes);
    }

    // Passages.

    [Fact]
    public void LargeCombination_IsSplitIntoPassesOfAtMostFourNotes()
    {
        // 190 = 50×3 + 20×2 : 5 billets, donc au moins deux passages.
        var (result, dispenser) = Run(250, 0, Full, null, 190);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(3, 2, 0), 5, new(55, 190)), result);
        Assert.True(dispenser.DispenseCalls.Count >= 2);
        Assert.All(dispenser.DispenseCalls, pass => Assert.InRange(pass.Total, 1, MoneyDispenser.MaxNotesPerPass));
        Assert.Equal(result.Notes, dispenser.DispenseCalls.Aggregate(NoteCounts.None, (a, b) => a + b));
        Assert.Equal(new NoteCounts(2, 3, 5), dispenser.Stock);
    }

    [Fact]
    public void TenNotes_NeedThreePasses()
    {
        // 150 sans billet de 50 : 20×5 + 10×5 = 10 billets.
        var (result, dispenser) = Run(250, 0, new(0, 5, 5), null, 150);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(0, 5, 5), 5, new(95, 150)), result);
        Assert.Equal(3, dispenser.DispenseCalls.Count);
        Assert.All(dispenser.DispenseCalls, pass => Assert.InRange(pass.Total, 1, MoneyDispenser.MaxNotesPerPass));
        Assert.Equal(NoteCounts.None, dispenser.Stock);
    }

    // Pannes.

    [Fact]
    public void DispenserFault_OnFirstPass_ReturnsNoNotes()
    {
        var dispenser = new RecordingDispenser(new MoneyDispenser(Full), failOnDispenseCall: 1);
        var result = new CashMachine(dispenser).Execute(new(250, 0), new Operation.Withdraw(60));

        Assert.Equal(new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, new(250, 0)), result);
        Assert.Single(dispenser.DispenseCalls);
    }

    [Fact]
    public void DispenserFault_OnLaterPass_ReturnsNotesAlreadyDispensedAndStops()
    {
        var dispenser = new RecordingDispenser(new MoneyDispenser(new(0, 5, 5)), failOnDispenseCall: 2);
        var result = new CashMachine(dispenser).Execute(new(250, 0), new Operation.Withdraw(150));

        Assert.Equal(AtmStatus.DispenserFault, result.Status);
        Assert.Equal(0, result.Fee);
        Assert.Equal(new AccountState(250, 0), result.Account);
        Assert.Equal(dispenser.DispenseCalls[0], result.Notes);
        Assert.Equal(2, dispenser.DispenseCalls.Count);
        Assert.Equal(new NoteCounts(0, 5, 5) - result.Notes, dispenser.Stock);
    }
}
